#ifndef GUARD_CONSTANTS_HOENN_LAYOUT_H
#define GUARD_CONSTANTS_HOENN_LAYOUT_H

// Hoenn & Seek: where Hoenn & Seek's own flags and vars live and how trainer
// flags are found. Everything here is stored in SaveBlock3 and reached through
// the hooks in GetFlagPointer/GetVarPointer (src/event_data.c -> src/hoenn_flags.c).
//
// ---- 1.0 range: generated by tools/hoenn/gen_hoenn_ids.py ----------------
// The generator hardcodes these numbers too. Keep them in sync.
//
// Flag 0x1800-0x1BFF  Hoenn story/item/hidden-item flags. Hidden-item flags
//                     come first: their offset from FLAG_HIDDEN_ITEMS_START is
//                     stored in 13 bits, so they must stay below 0x20E9.
//                     0x1BC0-0x1BFF are hand-defined (constants/hoenn_custom.h).
// Flag 0x1C00-0x1FFF  Hoenn trainer "defeated" flags (trainer ID - HOENN_TRAINERS_START),
//                     with the fake-fight flags borrowing 0x1F00-0x1FFF.
// Var  0x7000-0x707F  Hoenn vars (0x7070-0x707F hand-defined, constants/hoenn_custom.h).
//
// Storage: gSaveBlock3Ptr->hoennFlags / hoennVars.
//
// ---- 2.0 range: hand-defined, one block per build phase ---------------------
// Added in 2.0 part 1 for the new events. Nothing generates these; each part
// takes its flags from its phase's block in constants/hoenn_events.h.
//
// Flag 0x2000-0x23FF  Event flags (1,024). Sub-blocks:
//                       0x2000-0x203F  hidden items for 2.0 events (still below 0x20E9)
//                       0x2040-0x22FF  event flags by phase (constants/hoenn_events.h)
//                       0x2300-0x233F  daily flags, cleared with HnS's daily flags
//                       0x2340-0x237F  weekly flags, cleared once a week (part 2)
//                       0x2380-0x23FF  spare
// Var  0x7080-0x70FF  Event vars (128), by phase (constants/hoenn_events.h).
//
// Storage: gSaveBlock3Ptr->hoennEventFlags / hoennEventVars. They sit after the
// 1.0 arrays so the 1.0 layout (and the emulator harness's offsets) don't move;
// save version 6 clears them when a 1.0 save is loaded (src/save.c).
//
// ---- 2.1 range: hand-defined, one block per lane (2.1-02) ------------------
// Flag 0x2400-0x26FF  2.1 flags (768). Sub-blocks (constants/hoenn_events_2_1.h):
//                       0x2400-0x267F  event flags: shared, lane A, lane B,
//                                      the Seeker's Journal (generated), spare
//                       0x2680-0x26BF  daily flags, cleared with the 2.0 daily flags
//                       0x26C0-0x26FF  weekly flags, cleared with the 2.0 weekly flags
// Var  0x7100-0x713F  2.1 vars (64).
// 2.1 hidden items can't live here (the 13-bit limit, 0x20E9): they take the
// unused top of the 2.0 lanes' hidden-item ranges.
//
// Storage: gSaveBlock3Ptr->hoenn21Flags / hoenn21Vars, after the 2.0 arrays;
// save version 7 clears them when a 2.0 save is loaded (src/save.c).

// 1.0
#define HOENN_FLAGS_START           0x1800
#define HOENN_TRAINER_FLAGS_START   0x1C00
#define HOENN_FLAGS_END             0x1FFF
#define HOENN_FLAGS_BYTES           ((HOENN_FLAGS_END - HOENN_FLAGS_START + 1) / 8)
#define HOENN_VARS_START            0x7000
#define HOENN_VARS_COUNT            0x80
#define HOENN_CUSTOM_FLAGS_START    0x1BC0
#define HOENN_CUSTOM_VARS_START     0x7070

// 2.0
#define HOENN_EVENT_FLAGS_START     0x2000
#define HOENN_EVENT_FLAGS_END       0x23FF
#define HOENN_EVENT_FLAGS_BYTES     ((HOENN_EVENT_FLAGS_END - HOENN_EVENT_FLAGS_START + 1) / 8)
#define HOENN_EVENT_VARS_START      (HOENN_VARS_START + HOENN_VARS_COUNT) // 0x7080
#define HOENN_EVENT_VARS_COUNT      0x80

#define HOENN_EVENT_HIDDEN_ITEMS_START  0x2000 // 64 hidden-item flags
#define HOENN_EVENT_BLOCKS_START        0x2040 // phase blocks, constants/hoenn_events.h
#define HOENN_DAILY_FLAGS_START         0x2300 // 64 daily flags
#define HOENN_DAILY_FLAGS_END           0x233F
#define HOENN_WEEKLY_FLAGS_START        0x2340 // 64 weekly flags
#define HOENN_WEEKLY_FLAGS_END          0x237F

// 2.1
#define HOENN_21_FLAGS_START        0x2400
#define HOENN_21_FLAGS_END          0x26FF
#define HOENN_21_FLAGS_BYTES        ((HOENN_21_FLAGS_END - HOENN_21_FLAGS_START + 1) / 8)
#define HOENN_21_VARS_START         (HOENN_EVENT_VARS_START + HOENN_EVENT_VARS_COUNT) // 0x7100
#define HOENN_21_VARS_COUNT         0x40

#define HOENN_21_DAILY_FLAGS_START  0x2680 // 64 daily flags
#define HOENN_21_DAILY_FLAGS_END    0x26BF
#define HOENN_21_WEEKLY_FLAGS_START 0x26C0 // 64 weekly flags
#define HOENN_21_WEEKLY_FLAGS_END   0x26FF

#define IS_HOENN_1_0_FLAG(id)  ((id) >= HOENN_FLAGS_START && (id) <= HOENN_FLAGS_END)
#define IS_HOENN_EVENT_FLAG(id) ((id) >= HOENN_EVENT_FLAGS_START && (id) <= HOENN_EVENT_FLAGS_END)
#define IS_HOENN_21_FLAG(id)   ((id) >= HOENN_21_FLAGS_START && (id) <= HOENN_21_FLAGS_END)
// The three generations sit end to end (src/hoenn_flags.c checks it), so one
// range check covers them: GetFlagPointer/GetVarPointer are inlined widely.
#define IS_HOENN_FLAG(id)      ((id) >= HOENN_FLAGS_START && (id) <= HOENN_21_FLAGS_END)
#define IS_HOENN_1_0_VAR(id)   ((id) >= HOENN_VARS_START && (id) < HOENN_VARS_START + HOENN_VARS_COUNT)
#define IS_HOENN_EVENT_VAR(id) ((id) >= HOENN_EVENT_VARS_START && (id) < HOENN_EVENT_VARS_START + HOENN_EVENT_VARS_COUNT)
#define IS_HOENN_21_VAR(id)    ((id) >= HOENN_21_VARS_START && (id) < HOENN_21_VARS_START + HOENN_21_VARS_COUNT)
#define IS_HOENN_VAR(id)       ((id) >= HOENN_VARS_START && (id) < HOENN_21_VARS_START + HOENN_21_VARS_COUNT)

// The flag that records whether a trainer has been beaten.
#if IS_HNS && defined(HOENN_TRAINERS_START)
#define TRAINER_FLAG_ID(trainerId) ((u32)(trainerId) >= HOENN_TRAINERS_START && (u32)(trainerId) < TRAINERS_COUNT_HNS \
                                    ? HOENN_TRAINER_FLAGS_START + (trainerId) - HOENN_TRAINERS_START \
                                    : TRAINER_FLAGS_START + (trainerId))
#else
#define TRAINER_FLAG_ID(trainerId) (TRAINER_FLAGS_START + (trainerId))
#endif

#endif // GUARD_CONSTANTS_HOENN_LAYOUT_H
